// Good struct — small, immutable, value-like
readonly struct Money {
    public decimal Amount { get; }
    public string Currency { get; }
    public Money(decimal amount, string currency) {
        Amount = amount;
        Currency = currency;
    }
}

// Bad struct — too large, mutable
struct BadExample {
    public string Name;     // reference type field = heap anyway
    public List<int> Items; // mutable collection
    // This should be a class!
}

struct Point { public int X; public int Y; }

void Move(Point p) {
    p.X = 99;  // modifies the COPY
}

var original = new Point { X = 1, Y = 2 };
Move(original);
Console.WriteLine(original.X);  // Still 1! (copy was modified)

// Fix: pass by reference
void MoveRef(ref Point p) {
    p.X = 99;  // modifies the ORIGINAL
}

MoveRef(ref original);
Console.WriteLine(original.X);  // Now 99 ✓

struct MyNumber : IComparable<MyNumber> {
    public int Value;
    public int CompareTo(MyNumber other) => Value.CompareTo(other.Value);
}

var a = new MyNumber { Value = 5 };

// Boxing — allocates on heap!
IComparable<MyNumber> boxed = a;  // BOXED copy

// No boxing — generic constraint
void Compare<T>(T x, T y) where T : IComparable<T> {
    Console.WriteLine(x.CompareTo(y));  // no boxing!
}
Compare(a, new MyNumber { Value = 3 });  // ✓ direct call

// Abstract class — shared state + behavior
abstract class PaymentProcessor {
    protected List<string> _log = new();  // shared state

    public void Process(decimal amount) {  // template method
        Validate(amount);
        ExecutePayment(amount);
        _log.Add($"Processed {amount}");
    }

    protected abstract void ExecutePayment(decimal amount);
    private void Validate(decimal amount) {
        if (amount <= 0) throw new ArgumentException();
    }
}

class StripeProcessor : PaymentProcessor {
    protected override void ExecutePayment(decimal amount) {
        // Stripe-specific logic
    }
}

interface IReadable {
    string Read();
}

interface IWritable {
    void Write(string data);
}

// Interface inheriting MULTIPLE interfaces
interface IReadWritable : IReadable, IWritable {
    void Flush();
}

// Must implement Read(), Write(), AND Flush()
class FileStream : IReadWritable {
    public string Read() => "data";
    public void Write(string data) { /* ... */ }
    public void Flush() { /* ... */ }
}

// Traditional using block
using (var conn = new SqlConnection(connString)) {
    conn.Open();
    // work with connection
}  // Dispose() called here automatically

// C# 8 using declaration (cleaner)
using var reader = new StreamReader("file.txt");
var text = reader.ReadToEnd();
// Dispose() called at end of method scope

// What 'using' compiles to:
var conn = new SqlConnection(connString);
try {
    conn.Open();
} finally {
    conn?.Dispose();  // ALWAYS runs, even on exception
}

// This creates LOH allocations (bad in loops):
for (int i = 0; i < 1000; i++) {
    var big = new byte[100_000]; // 100KB → LOH!
    Process(big);
}   // 1000 LOH allocations → fragmentation

// Better: rent from ArrayPool
for (int i = 0; i < 1000; i++) {
    var big = ArrayPool<byte>.Shared.Rent(100_000);
    try {
        Process(big);
    } finally {
        ArrayPool<byte>.Shared.Return(big); // reused!
    }
}

// Query is DEFINED here — NOT executed
var query = db.Users.Where(u => u.Age > 18);

// Still not executed — just composing
query = query.OrderBy(u => u.Name);
query = query.Take(10);

// NOW it executes (one SQL query for everything above)
var results = query.ToList();
// SQL: SELECT TOP 10 * FROM Users WHERE Age > 18 ORDER BY Name

// Gotcha: multiple enumeration
var count = query.Count();   // executes AGAIN!
var first = query.First();   // executes AGAIN!

// BAD — returns IEnumerable
public IEnumerable<User> GetUsers() {
    return _db.Users;  // implicit cast to IEnumerable
}

var active = GetUsers()
    .Where(u => u.IsActive)  // filtered in C# memory!
    .ToList();
// SQL: SELECT * FROM Users  ← loads ALL rows

// GOOD — returns IQueryable
public IQueryable<User> GetUsers() {
    return _db.Users;
}

var active = GetUsers()
    .Where(u => u.IsActive)  // translated to SQL WHERE
    .ToList();
// SQL: SELECT * FROM Users WHERE IsActive = 1  ← only matching rows

// Library method — use ConfigureAwait(false)
public async Task<string> FetchDataAsync(string url) {
    var response = await _client.GetAsync(url)
        .ConfigureAwait(false);  // don't need UI thread
    return await response.Content.ReadAsStringAsync()
        .ConfigureAwait(false);
}

// UI code — do NOT use ConfigureAwait(false)
async void Button_Click(object sender, EventArgs e) {
    var data = await FetchDataAsync(url);
    label.Text = data;  // needs UI thread!
}

// ❌ COMPILER ERROR — cannot await in lock
lock (_obj) {
    await Task.Delay(100);  // CS1996 error!
}

// ✅ Use SemaphoreSlim instead
private readonly SemaphoreSlim _sem = new(1, 1);

async Task SafeMethodAsync() {
    await _sem.WaitAsync();  // async-friendly lock
    try {
        await Task.Delay(100);  // safe!
    } finally {
        _sem.Release();
    }
}

readonly struct LargeData {
    public readonly double X, Y, Z, W;  // 32 bytes
    public readonly string Name;
}

// Without 'in' — copies 32+ bytes every call
void Process(LargeData data) { /* ... */ }

// With 'in' — passes 8-byte reference, no copy
void ProcessFast(in LargeData data) {
    Console.WriteLine(data.X);  // read OK
    // data.X = 5;  // COMPILER ERROR — read-only!
}

class Person { public string Name { get; set; } }

void ChangeName(Person p) {
    p.Name = "Bob";        // mutates the SAME object ✓
    p = new Person();       // only changes local copy
}

void ChangeRef(ref Person p) {
    p = new Person { Name = "Eve" };  // changes caller's variable!
}

var person = new Person { Name = "Alice" };
ChangeName(person);
Console.WriteLine(person.Name);  // "Bob" (mutated)
// person still points to original object

ChangeRef(ref person);
Console.WriteLine(person.Name);  // "Eve" (reassigned!)
